package com.example.helpdesk.service;
import com.example.helpdesk.model.*;import com.example.helpdesk.repo.*;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;
@Service public class TicketService{
 private final TicketRepository tickets;private final UserRepository users;private final CategoryRepository cats;private final CommentRepository comments;
 public TicketService(TicketRepository t,UserRepository u,CategoryRepository c,CommentRepository cm){tickets=t;users=u;cats=c;comments=cm;}
 public Page<Ticket> list(AppUser u,int page,int size,TicketStatus st,Priority pr,String cat,Long agent,LocalDate from,LocalDate to){if(u.getRole()!=Role.ADMIN)agent=null;return tickets.filtered(u.getRole().name(),u.getId(),st,pr,cat,agent,from==null?null:from.atStartOfDay(),to==null?null:to.plusDays(1).atStartOfDay().minusNanos(1),PageRequest.of(Math.max(0,page),Math.min(Math.max(size,1),100),Sort.by(Sort.Direction.DESC,"createdAt")));}
 @Transactional public Ticket create(AppUser u,String title,String desc,Long cat,Priority pr){Ticket t=new Ticket();t.setTitle(title);t.setDescription(desc);t.setRequester(u);t.setCategory(cats.findById(cat).orElseThrow(()->new IllegalArgumentException("Category not found")));t.setPriority(pr);return tickets.save(t);}
 public Ticket get(AppUser u,Long id){Ticket t=tickets.findById(id).orElseThrow(()->new NoSuchElementException("Ticket not found"));if(u.getRole()==Role.USER&&!t.getRequester().getId().equals(u.getId()))throw new SecurityException("Not allowed");if(u.getRole()==Role.AGENT&&(t.getAssignedAgent()==null||!t.getAssignedAgent().getId().equals(u.getId())))throw new SecurityException("Not allowed");return t;}
 @Transactional public Ticket status(AppUser u,Long id,TicketStatus st,String notes){Ticket t=get(u,id);if(u.getRole()==Role.USER&&(st!=TicketStatus.CLOSED||t.getStatus()!=TicketStatus.RESOLVED))throw new SecurityException("Users may only close resolved tickets");if(st==TicketStatus.CLOSED&&u.getRole()==Role.AGENT)throw new SecurityException("Only requester or admin can close a ticket");t.setStatus(st);if(notes!=null)t.setResolutionNotes(notes);return tickets.save(t);}
 @Transactional public Ticket assign(Long id,Long aid){Ticket t=tickets.findById(id).orElseThrow(()->new NoSuchElementException("Ticket not found"));AppUser a=users.findById(aid).orElseThrow(()->new IllegalArgumentException("Agent not found"));if(a.getRole()!=Role.AGENT)throw new IllegalArgumentException("Assignee must be an agent");t.setAssignedAgent(a);if(t.getStatus()==TicketStatus.OPEN)t.setStatus(TicketStatus.ASSIGNED);return tickets.save(t);}
 @Transactional public TicketComment comment(AppUser u,Long id,String body){Ticket t=get(u,id);TicketComment c=new TicketComment();c.setTicket(t);c.setAuthor(u);c.setBody(body);return comments.save(c);}
 public List<TicketComment> comments(AppUser u,Long id){get(u,id);return comments.findByTicketIdOrderByCreatedAtAsc(id);}
 public Map<String,Object> stats(){Map<String,Object> m=new LinkedHashMap<>();for(TicketStatus s:TicketStatus.values())m.put(s.name().toLowerCase(),tickets.countByStatus(s));return m;}
}
